def count_reachable_integers(N, X, A):
    @lru_cache(maxsize=None)
    def dfs(state, remaining):
        if remaining < 0:
            return 0
        count = 1 if state <= X else 0
        for i in range(N):
            if state & (1 << i):
                count = (count + dfs(state, remaining - 1)) % MOD
                count = (count + dfs(state ^ (1 << i), remaining - 1)) % MOD
        return count

    initial_state = 0
    for i in range(N):
        initial_state |= A[i] << i

    return dfs(initial_state, 4000)

