def count_integers(N, X, A):
    MOD = 998244353

    # Use a set to track all possible values on the board
    possible_values = set(A)

    # Use a list to process the values layer by layer
    current_layer = list(A)

    while current_layer:
        next_layer = []
        for x in current_layer:
            # Double operation
            doubled = 2 * x
            if doubled <= X:
                if doubled not in possible_values:
                    possible_values.add(doubled)
                    next_layer.append(doubled)

            # XOR operation
            for y in current_layer:
                xor_result = x ^ y
                if xor_result <= X:
                    if xor_result not in possible_values:
                        possible_values.add(xor_result)
                        next_layer.append(xor_result)

        # Move to the next layer
        current_layer = next_layer

    return len(possible_values)

